package com.lianxibu.site.service.jobs;

import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.jobs.ResultApplicationService.Input;
import java.nio.charset.StandardCharsets;
import java.util.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Complete frozen proof constraints. Parsing this frame cannot create a native Projection or commit permit. */
public final class FrozenCatalogVersionProjections {
    public static final String FIELD="catalog_version_projections_v1";
    public static final int MAX_BYTES=1048576,MAX_ITEMS=100;
    public static final class Entry {
        private final String json,hash,key,item,entity,content,cutoff;
        private Entry(JsonNode p,String hash){json=canonical(p);this.hash=hash;key=text(p,"judgment_key");item=text(p,"item_id");entity=text(p,"entity_id");content=text(p,"content_id");cutoff=text(p,"cutoff");}
        public String json(){return json;}public String hash(){return hash;}public String judgmentKey(){return key;}public String itemId(){return item;}public String entityId(){return entity;}public String contentId(){return content;}public java.time.Instant cutoff(){return java.time.Instant.parse(cutoff);}
        public boolean matches(CatalogVersionQualificationProjection.Projection fresh){return fresh!=null&&hash.equals(fresh.hash())&&json.equals(fresh.json());}
        @Override public String toString(){return "FrozenCatalogVersionProjection[redacted]";}
    }
    private final String json;private final Map<String,Entry> entries;
    private FrozenCatalogVersionProjections(String json,Map<String,Entry> entries){this.json=json;this.entries=Map.copyOf(entries);}
    public String json(){return json;}public JsonNode toJson(){return CanonicalJson.parse(json);}public Map<String,Entry> entries(){return entries;}
    public static FrozenCatalogVersionProjections create(Collection<CatalogVersionQualificationProjection.Projection> original,Input input){
        Objects.requireNonNull(original);if(original.size()>MAX_ITEMS)throw new GenerationFlowService.CapacityGuarded();var n=JsonMapper.shared().createObjectNode().put("schema_version","catalog-version-projections-v1");var items=n.putArray("items");original.stream().sorted((a,b)->utf8(a.memberId(),b.memberId())).forEach(p->{var row=items.addObject().put("projection_hash",p.hash());row.set("projection",p.toJson());});return read(n,input);
    }
    public static FrozenCatalogVersionProjections read(JsonNode original,Input input){
        try{
            Objects.requireNonNull(input);if(!"2".equals(input.dedupResultVersion())||!Set.of(GenerationFlowService.Stage.AGENT_DEDUP,GenerationFlowService.Stage.SKILL_DEDUP,GenerationFlowService.Stage.WORKFLOW_DEDUP,GenerationFlowService.Stage.MODEL_DEDUP).contains(input.stage())||input.itemIds().size()>MAX_ITEMS)throw invalid();
            if(original==null)throw invalid();byte[] bytes=CanonicalJson.bytes(original);if(bytes.length>MAX_BYTES)throw new GenerationFlowService.CapacityGuarded();var n=CanonicalJson.parse(bytes);var fields=Set.of("schema_version","items");WireValues.object(n,fields,fields);if(!"catalog-version-projections-v1".equals(text(n,"schema_version")))throw invalid();var items=n.get("items");if(!items.isArray()||items.size()>MAX_ITEMS)throw invalid();var values=new HashMap<String,Entry>();String last=null,category=input.stage().name().toLowerCase(Locale.ROOT).replace("_dedup","");
            for(var row:items){var names=Set.of("projection_hash","projection");WireValues.object(row,names,names);String hash=WireValues.sha256(row.get("projection_hash"));var p=row.get("projection");validate(p,category);if(!hash.equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,p)))throw invalid();var entry=new Entry(p,hash);var q=input.catalogVersionQualifications().get(entry.itemId());
                if(q==null||!q.entityId().equals(entry.entityId())||q.versionChanged()!=p.get("version_changed").booleanValue()||!q.previousProofHash().equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,p.get("previous_proof")))||!q.newProofHash().equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,p.get("current_proof")))||!input.itemIds().contains(entry.itemId())||!input.candidatesByItem().getOrDefault(entry.itemId(),Set.of()).contains(entry.entityId())||values.putIfAbsent(entry.itemId(),entry)!=null||last!=null&&utf8(last,entry.itemId())>=0)throw invalid();last=entry.itemId();
            }
            if(!values.keySet().equals(input.catalogVersionQualifications().keySet()))throw invalid();return new FrozenCatalogVersionProjections(new String(bytes,StandardCharsets.UTF_8),values);
        }catch(GenerationFlowService.CapacityGuarded guarded){throw guarded;}catch(RuntimeException rejected){throw invalid();}
    }
    private static void validate(JsonNode p,String category){
        var fields=Set.of("schema_version","category","entity_id","content_id","root_id","item_id","version_changed","judgment_key","claim_target_hash","entity_revision","entity_generation","content_revision","content_body_revision","content_body_hash","input_hash","result_hash","generation","cutoff","input_cutoff","applied_at","previous_proof","current_proof","current_marker");WireValues.object(p,fields,fields);if(CanonicalJson.bytes(p).length>CatalogVersionQualificationProjection.MAX_BYTES||!"catalog-version-qualification-projection-v1".equals(text(p,"schema_version"))||!category.equals(text(p,"category"))||!p.get("version_changed").isBoolean())throw invalid();
        for(String name:List.of("entity_id","content_id","root_id","item_id"))WireValues.id(p.get(name),false);for(String name:List.of("judgment_key","claim_target_hash","content_body_hash","input_hash","result_hash"))WireValues.sha256(p.get(name));for(String name:List.of("entity_revision","entity_generation","content_revision","content_body_revision","generation"))WireValues.nonnegativeInteger(p.get(name));if(number(p,"generation")<1||number(p,"entity_generation")<number(p,"generation")||number(p,"content_body_revision")<1)throw invalid();var cutoff=WireValues.utcMicroseconds(p.get("cutoff"));if(cutoff.isBefore(WireValues.utcMicroseconds(p.get("applied_at")))||WireValues.utcMicroseconds(p.get("applied_at")).isBefore(WireValues.utcMicroseconds(p.get("input_cutoff"))))throw invalid();
        var previous=p.get("previous_proof");var oldFields=Set.of("schema_version","category","entity_id","root_id","generation","input_hash","result_hash","semantic_hash","members");WireValues.object(previous,oldFields,oldFields);if(CanonicalJson.bytes(previous).length>65536||!"catalog-previous-version-proof-v1".equals(text(previous,"schema_version")))throw invalid();for(String name:List.of("category","entity_id","root_id","input_hash","result_hash"))if(!text(previous,name).equals(text(p,name)))throw invalid();if(number(previous,"generation")!=number(p,"generation"))throw invalid();WireValues.sha256(previous.get("semantic_hash"));var members=previous.get("members");if(!members.isArray()||members.isEmpty()||members.size()>100)throw invalid();var ids=new HashSet<String>();var versions=new TreeSet<String>();
        for(var member:members){var names=Set.of("item_id","body_hash","version_hash");WireValues.object(member,names,names);if(!ids.add(WireValues.id(member.get("item_id"),false)))throw invalid();WireValues.sha256(member.get("body_hash"));versions.add(WireValues.sha256(member.get("version_hash")));}
        var current=p.get("current_proof");var newFields=Set.of("schema_version","category","entity_id","entity_revision","entity_generation","source_id","run_id","item_id","member_revision","config_version","config_hash","body_hash","version_hash","qualification_hash");WireValues.object(current,newFields,newFields);if(CanonicalJson.bytes(current).length>16384||!"catalog-current-version-proof-v1".equals(text(current,"schema_version")))throw invalid();for(String name:List.of("category","entity_id","item_id"))if(!text(current,name).equals(text(p,name)))throw invalid();for(String name:List.of("entity_revision","entity_generation"))if(number(current,name)!=number(p,name))throw invalid();WireValues.id(current.get("source_id"),true);WireValues.id(current.get("run_id"),false);WireValues.nonnegativeInteger(current.get("member_revision"));if(number(current,"config_version")<1)throw invalid();for(String name:List.of("config_hash","body_hash","version_hash","qualification_hash"))WireValues.sha256(current.get(name));
        var marker=p.get("current_marker");var markerFields=Set.of("schema_version","category","identity","version");WireValues.object(marker,markerFields,markerFields);var identityFields=Set.of("namespace","key");WireValues.object(marker.get("identity"),identityFields,identityFields);if(CanonicalJson.bytes(marker).length>16384||!"catalog-version-marker-v1".equals(text(marker,"schema_version"))||!category.equals(text(marker,"category"))||!marker.get("version").isObject()||!Set.of("release","skill_document","benchmark_result").contains(text(marker.get("version"),"kind"))||!text(current,"version_hash").equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,marker)))throw invalid();
        var semantic=JsonMapper.shared().createObjectNode().put("schema_version","catalog-previous-version-profile-v1").put("category",category);semantic.set("identity",marker.get("identity"));var hashes=semantic.putArray("version_hashes");versions.forEach(hashes::add);if(!text(previous,"semantic_hash").equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,semantic))||p.get("version_changed").booleanValue()==versions.contains(text(current,"version_hash")))throw invalid();
        var definition=JsonMapper.shared().createObjectNode().put("schema_version","catalog-version-qualification-v1").put("category",category).put("source_id",text(current,"source_id")).put("config_hash",text(current,"config_hash"));if(!text(current,"qualification_hash").equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,definition)))throw invalid();var key=JsonMapper.shared().createObjectNode().put("schema_version","catalog-version-judgment-key-v1").put("category",category).put("entity_id",text(p,"entity_id")).put("version_hash",text(current,"version_hash")).put("qualification_hash",text(current,"qualification_hash"));if(!text(p,"judgment_key").equals(CanonicalJson.hash(CanonicalJson.Domain.INPUT,key)))throw invalid();
    }
    private static String text(JsonNode n,String name){return WireValues.text(n.get(name));}private static long number(JsonNode n,String name){return WireValues.nonnegativeInteger(n.get(name));}
    private static String canonical(JsonNode n){return new String(CanonicalJson.bytes(n),StandardCharsets.UTF_8);}private static int utf8(String a,String b){return Arrays.compareUnsigned(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}
    private static IllegalArgumentException invalid(){return new IllegalArgumentException("original frozen catalog version projections unavailable");}
}
